use std::future::Future;

trait Store {
    fn load(&self) -> impl Future<Output = u32> + Send;

    fn load_twice(&self) -> impl Future<Output = u32> + Send {
        async { self.load().await + self.load().await }
    }
}

use std::collections::BTreeSet;

fn validate(questions: &[u32], answers: &[u32]) -> Result<(), String> {
    for a in answers {
        let mut seen = BTreeSet::new();
        if !questions.contains(a) {
            return Err(format!("unknown question {a}"));
        }
        if !seen.insert(a) {
            return Err(format!("two answers to question {a}"));
        }
    }
    Ok(())
}

